40	/* base64 for Sec-WebSocket-Key (16 random bytes → 24 chars) */
41	static void b64_encode(const unsigned char *in, int inlen,
42	                       char *out, int outcap)
43	{
44	    static const char tbl[] =
45	        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
46	    int i = 0, o = 0;
47	    while (i + 2 < inlen && o + 4 < outcap)
48	        {
49	            unsigned int v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
50	            out[o++] = tbl[(v >> 18) & 63];
51	            out[o++] = tbl[(v >> 12) & 63];
52	            out[o++] = tbl[(v >> 6) & 63];
53	            out[o++] = tbl[v & 63];
54	            i += 3;
55	        }
56	    out[o] = '\0';
57	}
