69	            hdr[hlen++] = (unsigned char)(0x80 | len);
70	        }
71	    else if (len < 65536)
72	        {
73	            hdr[hlen++] = 0x80 | 126;
74	            hdr[hlen++] = (unsigned char)(len >> 8);
75	            hdr[hlen++] = (unsigned char)(len & 0xFF);
