81	                hdr[hlen++] = (unsigned char)((len >> (i * 8)) & 0xFF);
82	        }
83	
84	    unsigned char mask[4] = { 0x12, 0x34, 0x56, 0x78 };
85	    memcpy(hdr + hlen, mask, 4);
86	    hlen += 4;
87	
88	    if (send(fd, hdr, hlen, 0) != hlen)
89	        return -1;
90	
91	    for (size_t off = 0; off < len; )
92	        {
93	            size_t todo = len - off;
94	            unsigned char chunk[128];
95	            if (todo > sizeof(chunk))
96	                todo = sizeof(chunk);
97	            for (size_t i = 0; i < todo; i++)
98	                chunk[i] = (unsigned char)text[off + i] ^ mask[(off + i) & 3];
99	            if (send(fd, chunk, todo, 0) != (int)todo)
100	                return -1;
101	            off += todo;
102	        }
103	    return 0;
104	}
