106	/* Receive one text frame (server → client, unmasked). Returns payload len,
107	 * -1 on error/close. */
108	static int ws_recv_text(int fd, char *out, int outcap)
109	{
110	    unsigned char b0, b1;
111	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
112	        return -1;
113	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
114	        return -1;
115	
116	    int opcode = b0 & 0x0F;
117	    size_t plen = b1 & 0x7F;
118	    int masked = (b1 & 0x80) != 0;
119	
120	    if (plen == 126)
121	        {
122	            unsigned char ext[2];
123	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
124	                return -1;
125	            plen = (ext[0] << 8) | ext[1];
126	        }
127	    else if (plen == 127)
128	        {
129	            unsigned char ext[8];
130	            if (recv(fd, ext, 8, MSG_WAITALL) != 8)
131	                return -1;
132	            plen = 0;
133	            for (int i = 0; i < 8; i++)
134	                plen = (plen << 8) | ext[i];
135	        }
136	
137	    unsigned char mask[4] = { 0, 0, 0, 0 };
138	    if (masked)
139	        {
140	            if (recv(fd, mask, 4, MSG_WAITALL) != 4)
141	                return -1;
142	        }
143	
144	    if (opcode == 0x8)                  /* close */
145	        return -1;
146	    if (opcode == 0x9)                  /* ping → pong */
147	        {
148	            unsigned char pong[2] = { 0x8A, 0x00 };
149	            send(fd, pong, 2, 0);
150	            return 0;
151	        }
152	    if (opcode != 0x1)                  /* ignore non-text */
153	        {
154	            unsigned char discard[256];
155	            size_t left = plen;
156	            while (left > 0)
157	                {
158	                    size_t todo = left > sizeof(discard) ?
159	                                  sizeof(discard) : left;
160	                    if (recv(fd, discard, todo, MSG_WAITALL) != (int)todo)
161	                        return -1;
162	                    left -= todo;
163	                }
164	            return 0;
165	        }
166	
167	    if ((int)plen >= outcap)
168	        plen = outcap - 1;
169	    size_t got = 0;
170	    while (got < plen)
171	        {
172	            int n = recv(fd, out + got, plen - got, 0);
173	            if (n <= 0)
174	                return -1;
175	            got += n;
176	        }
177	    for (size_t i = 0; i < got; i++)
178	        out[i] ^= mask[i & 3];
179	    out[got] = '\0';
180	    return (int)got;
181	}
