183	/* Extract "content":"..." value from a JSON response */
184	static void extract_content(const char *json, char *out, int outcap)
185	{
186	    const char *p = strstr(json, "\"content\"");
187	    if (!p)
188	        {
189	            out[0] = '\0';
190	            return;
191	        }
192	    p = strchr(p, ':');
193	    if (!p)
194	        {
195	            out[0] = '\0';
196	            return;
197	        }
198	    p = strchr(p, '"');
199	    if (!p)
200	        {
201	            out[0] = '\0';
202	            return;
203	        }
204	    p++;
205	    int o = 0;
206	    while (*p && *p != '"' && o < outcap - 1)
207	        {
208	            if (*p == '\\' && (p[1] == 'n' || p[1] == 't' || p[1] == '"'))
209	                {
210	                    out[o++] = (p[1] == 'n') ? '\n' : (p[1] == 't') ? '\t' : '"';
211	                    p += 2;
212	                }
213	            else
214	                {
215	                    out[o++] = *p++;
216	                }
217	        }
218	    out[o] = '\0';
219	}
