148	static int do_ws_handshake(int fd, char* chat_id_out, size_t chat_id_size)
149	{
150	    char buf[1024];
151	    int total = 0;
152	
153	    /* Read until we see the end of headers */
154	    while (total < (int)sizeof(buf) - 1) {
155	        int n = recv(fd, buf + total, sizeof(buf) - 1 - total, 0);
156	        if (n <= 0)
157	            return -1;
158	        total += n;
159	        buf[total] = '\0';
160	        if (strstr(buf, "\r\n\r\n"))
161	            break;
162	    }
163	
164	    /* Extract Sec-WebSocket-Key */
165	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
166	    if (!key_hdr) {
167	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
168	        return -1;
169	    }
170	    key_hdr += 21;
171	    char* eol = strstr(key_hdr, "\r\n");
172	    if (!eol)
173	        return -1;
174	
175	    char ws_key[128] = { 0 };
176	    size_t klen = (size_t)(eol - key_hdr);
177	    if (klen >= sizeof(ws_key))
178	        return -1;
179	    memcpy(ws_key, key_hdr, klen);
180	    ws_key[klen] = '\0';
181	
182	    /* Compute accept */
183	    char accept[64] = { 0 };
184	    if (make_accept_key(ws_key, accept, sizeof(accept)) < 0)
185	        return -1;
186	
187	    /* Send 101 */
188	    char resp[512];
189	    int rlen = snprintf(resp, sizeof(resp),
190	        "HTTP/1.1 101 Switching Protocols\r\n"
191	        "Upgrade: websocket\r\n"
192	        "Connection: Upgrade\r\n"
193	        "Sec-WebSocket-Accept: %s\r\n\r\n",
194	        accept);
195	    if (send(fd, resp, rlen, 0) != rlen)
196	        return -1;
197	
198	    /* Default chat_id from fd (may be overridden by first message) */
199	    snprintf(chat_id_out, chat_id_size, "ws_%d", fd);
200	    return 0;
201	}
