203	/* ── WS frame encode/decode ───────────────────────────────────── */
204	
205	/**
206	 * Send a text frame (server → client, no masking).
207	 * Caller must hold s_clients_mtx.
208	 */
209	static int ws_send_frame(int fd, const char* payload, size_t len)
210	{
211	    unsigned char hdr[10];
212	    int hdr_len = 0;
213	
214	    hdr[0] = 0x81; /* FIN + text opcode */
215	    if (len < 126) {
216	        hdr[1] = (unsigned char)len;
217	        hdr_len = 2;
218	    } else if (len < 65536) {
219	        hdr[1] = 126;
220	        hdr[2] = (unsigned char)(len >> 8);
221	        hdr[3] = (unsigned char)(len & 0xFF);
222	        hdr_len = 4;
223	    } else {
224	        syslog(LOG_ERR, "[%s] Payload too large: %d\n", TAG, (int)len);
225	        return -1;
226	    }
227	
228	    if (send(fd, hdr, hdr_len, 0) != hdr_len)
229	        return -1;
230	    if (send(fd, payload, len, 0) != (int)len)
231	        return -1;
232	    return 0;
233	}
