235	/**
236	 * Read and decode one WS frame; place text payload into buf (NUL-terminated).
237	 * Returns payload length on success, 0 on close frame, -1 on error.
238	 */
239	static int ws_recv_frame(int fd, char* buf, size_t buf_size)
240	{
241	    unsigned char b0, b1;
242	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
243	        return -1;
244	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
245	        return -1;
246	
247	    int opcode = b0 & 0x0F;
248	    bool masked = (b1 & 0x80) != 0;
249	    size_t plen = b1 & 0x7F;
250	
251	    if (opcode == 0x8)
252	        return 0; /* Close frame */
253	
254	    if (opcode == 0x9 || opcode == 0xA) {
255	        /* Ping (0x9) or Pong (0xA) — must consume payload before returning,
256	         * otherwise leftover bytes corrupt the next frame read. */
257	        if (plen == 126) {
258	            unsigned char ext[2];
259	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
260	                return -1;
261	            plen = ((size_t)ext[0] << 8) | ext[1];
262	        } else if (plen == 127) {
263	            return -1;
264	        }
265	
266	        unsigned char pp_mask[4] = { 0 };
267	        if (masked) {
268	            if (recv(fd, pp_mask, 4, MSG_WAITALL) != 4)
269	                return -1;
270	        }
271	
272	        if (plen > 125) {
273	            syslog(LOG_ERR,
274	                "[%s] Invalid control frame payload length: %d\n",
275	                TAG, (int)plen);
276	            return -1;
277	        }
278	
279	        /* Read full control payload so ping can be echoed in pong. */
280	        unsigned char ctrl_payload[125] = { 0 };
281	        if (plen > 0) {
282	            if (recv(fd, ctrl_payload, plen, MSG_WAITALL) != (int)plen)
283	                return -1;
284	
285	            if (masked) {
286	                for (size_t i = 0; i < plen; i++) {
287	                    ctrl_payload[i] ^= pp_mask[i % 4];
288	                }
289	            }
290	        }
291	
292	        /* Reply with pong if it was a ping */
293	        if (opcode == 0x9) {
294	            unsigned char pong_hdr[2] = { 0x8A, (unsigned char)plen };
295	            send(fd, pong_hdr, 2, 0);
296	            if (plen > 0) {
297	                send(fd, ctrl_payload, plen, 0);
298	            }
299	        }
300	        return -2;
301	    }
302	
303	    if (opcode != 0x1 && opcode != 0x2) {
304	        /* Unknown opcode — skip */
305	        return -2;
306	    }
307	
308	    if (plen == 126) {
309	        unsigned char ext[2];
310	        if (recv(fd, ext, 2, MSG_WAITALL) != 2)
311	            return -1;
312	        plen = ((size_t)ext[0] << 8) | ext[1];
313	    } else if (plen == 127) {
314	        syslog(LOG_ERR, "[%s] 64-bit frame length not supported\n", TAG);
315	        return -1;
316	    }
317	
318	    unsigned char mask_key[4] = { 0 };
319	    if (masked) {
320	        if (recv(fd, mask_key, 4, MSG_WAITALL) != 4)
321	            return -1;
322	    }
323	
324	    if (plen >= buf_size) {
325	        syslog(LOG_ERR, "[%s] Frame too large: %d\n", TAG, (int)plen);
326	        return -1;
327	    }
328	
329	    int received = 0;
330	    while ((size_t)received < plen) {
331	        int n = recv(fd, buf + received, plen - received, 0);
332	        if (n <= 0)
333	            return -1;
334	        received += n;
335	    }
336	
337	    if (masked) {
338	        for (size_t i = 0; i < plen; i++) {
339	            ((unsigned char*)buf)[i] ^= mask_key[i % 4];
340	        }
341	    }
342	
343	    buf[plen] = '\0';
344	    return (int)plen;
345	}
