347	/* ── Per-client thread ────────────────────────────────────────── */
348	
349	typedef struct {
350	    int fd;
351	} client_arg_t;
352	
353	static void* client_thread(void* arg)
354	{
355	    client_arg_t ca = *(client_arg_t*)arg;
356	    free(arg);
357	    int fd = ca.fd;
358	
359	    /* Handshake */
360	    char chat_id[32];
361	    if (do_ws_handshake(fd, chat_id, sizeof(chat_id)) != 0) {
362	        syslog(LOG_WARNING, "[%s] Handshake failed for fd=%d\n", TAG, fd);
363	        close(fd);
364	        return NULL;
365	    }
366	
367	    /* Register client */
368	    pthread_mutex_lock(&s_clients_mtx);
369	    ws_client_t* client = add_client_locked(fd);
370	    if (!client) {
371	        pthread_mutex_unlock(&s_clients_mtx);
372	        syslog(LOG_WARNING, "[%s] Max clients reached, closing fd=%d\n", TAG, fd);
373	        /* Politely close */
374	        unsigned char close_frame[2] = { 0x88, 0x00 };
375	        send(fd, close_frame, 2, 0);
376	        close(fd);
377	        return NULL;
378	    }
379	    snprintf(client->chat_id, sizeof(client->chat_id), "%s", chat_id);
380	    pthread_mutex_unlock(&s_clients_mtx);
381	
382	    /* Send connect.challenge so Nodes can identify themselves */
383	#ifdef CONFIG_AI_AGENT_NODE
384	    node_manager_send_challenge(fd);
385	#endif
386	
387	    /* Read loop — stack-allocated so each client thread has its own buffer */
388	    char frame_buf[4096];
