161	void audio_capture_close(audio_capture_t* cap)
162	{
163	    if (!cap) {
164	        return;
165	    }
166	
167	    if (cap->recorder) {
168	        int ret;
169	
170	        /* media_recorder_stop() internally closes the audio stream
171	         * (af_stream_stop + af_stream_close).  media_recorder_close()
172	         * then tries af_stream_close again, which logs a harmless
173	         * "ERROR: status = 1" because the stream is already closed.
174	         *
175	         * This double-close warning is benign.  Removing the stop()
176	         * call is NOT safe — media_recorder_close() alone does not
177	         * properly release the pcm0c stream, leaving it in a stale
178	         * state that blocks the next recorder open. */
179	        ret = media_recorder_stop(cap->recorder);
180	        if (ret < 0) {
181	            syslog(LOG_WARNING, "[%s] media_recorder_stop: %d\n", TAG, ret);
182	        }
183	
184	        /* Brief delay to let media framework's internal thread
185	         * finish processing the stop command before we close.
186	         * Without this, af_stream_close races with the recorder
187	         * thread's own close, causing "status = 1" errors on
188	         * BES platforms. */
189	        usleep(50 * 1000);
190	
191	        ret = media_recorder_close(cap->recorder);
192	        if (ret < 0) {
193	            syslog(LOG_WARNING, "[%s] media_recorder_close: %d\n", TAG, ret);
194	        }
195	
196	        cap->recorder = NULL;
197	        s_active_recorder = NULL;
198	    }
199	
200	    free(cap);
201	}

