457	static void* accept_thread(void* arg)
458	{
459	    (void)arg;
460	    while (s_running) {
461	        struct pollfd pfd = { .fd = s_listen_fd, .events = POLLIN };
462	        int pr = poll(&pfd, 1, 500);
463	        if (pr <= 0)
464	            continue;
465	
466	        struct sockaddr_in addr;
467	        socklen_t addr_len = sizeof(addr);
468	        int cfd = accept(s_listen_fd, (struct sockaddr*)&addr, &addr_len);
469	        if (cfd < 0)
470	            continue;
471	
472	        client_arg_t* ca = malloc(sizeof(client_arg_t));
473	        if (!ca) {
474	            close(cfd);
475	            continue;
476	        }
477	        ca->fd = cfd;
478	
479	        pthread_t tid;
480	        pthread_attr_t attr;
481	        pthread_attr_init(&attr);
482	        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
483	        pthread_attr_setstacksize(&attr, AGENT_WS_CLIENT_STACK);
484	        if (pthread_create(&tid, &attr, client_thread, ca) != 0) {
485	            free(ca);
486	            close(cfd);
487	        }
488	        pthread_attr_destroy(&attr);
489	    }
490	    return NULL;
491	}
