17	/* audio_playback.c — Streaming audio playback via media_player buffer mode.
18	 *
19	 * Uses media_player_write_data() for synchronous buffer-mode playback.
20	 * Each write_data() call blocks until the media framework consumes the
21	 * buffer, so TTS PCM chunks are played as they arrive — no temp file. */
22	
23	#include "voice/audio_playback.h"
24	#include "agent_config.h"
25	
26	#include <errno.h>
27	#include <media_player.h>
28	#include <stdio.h>
29	#include <stdlib.h>
30	#include <string.h>
31	#include <syslog.h>
32	#include <unistd.h>
33	
34	static const char* TAG = "audio_pb";
35	
36	#define PB_OPTIONS_LEN 128
37	
38	static void* s_active_player;
39	
40	struct audio_playback {
41	    void* player;
42	    size_t total_written;
43	    unsigned int sample_rate;
44	    unsigned int channels;
45	    unsigned int bits_per_sample;
46	    volatile int stopped; /* set by audio_playback_stop() from another thread */
47	};
48	
49	audio_playback_t* audio_playback_open(const char* dev_path,
50	    unsigned int sample_rate, unsigned int channels,
51	    unsigned int bits_per_sample)
52	{
53	    (void)dev_path;
54	
55	    if (s_active_player) {
56	        syslog(LOG_WARNING, "[%s] force closing stale player\n", TAG);
57	        media_player_stop(s_active_player);
58	        media_player_close(s_active_player, 0);
59	        s_active_player = NULL;
60	        /* Let the media framework finish internal cleanup before
61	         * opening a new player.  Without this delay, the next
62	         * media_player_open may see stale state and request a
63	         * bogus allocation (observed: 1.3GB → assert crash). */
64	        usleep(100000); /* 100ms */
65	    }
66	
67	    void* player = media_player_open(MEDIA_STREAM_MUSIC);
68	
69	    if (!player) {
70	        syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
71	        return NULL;
72	    }
73	
74	    char opts[PB_OPTIONS_LEN];
75	
76	    snprintf(opts, sizeof(opts),
77	        "format=s%ule:sample_rate=%u:ch_layout=%s",
78	        bits_per_sample, sample_rate,
79	        (channels == 1) ? "mono" : "stereo");
80	
81	    /* Buffer mode: url=NULL, caller provides data via write_data() */
82	    int ret = media_player_prepare(player, NULL, opts);
83	
84	    if (ret < 0) {
85	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
86	        media_player_close(player, 0);
87	        return NULL;
88	    }
89	
90	    ret = media_player_start(player);
91	    if (ret < 0) {
92	        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
93	        media_player_close(player, 0);
94	        return NULL;
95	    }
96	
97	    audio_playback_t* pb = calloc(1, sizeof(*pb));
98	
99	    if (!pb) {
100	        media_player_close(player, 0);
101	        return NULL;
102	    }
103	
104	    pb->player = player;
105	    pb->sample_rate = sample_rate;
106	    pb->channels = channels;
107	    pb->bits_per_sample = bits_per_sample;
108	    pb->stopped = 0;
109	    s_active_player = player;
110	
111	    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit) buffer mode\n",
112	        TAG, sample_rate, channels, bits_per_sample);
113	    return pb;
114	}
115	
116	int audio_playback_write(audio_playback_t* pb,
117	    const void* buf, size_t len)
118	{
119	    if (!pb || !pb->player || !buf || len == 0) {
120	        return -EINVAL;
121	    }
122	
123	    /* AEC workaround: voice_channel_start() sets stopped to skip
124	     * remaining TTS chunks and prevent echo into the microphone. */
125	    if (pb->stopped) {
126	        return -ECANCELED;
127	    }
128	
129	    ssize_t n = media_player_write_data(pb->player, buf, len);
130	
131	    if (n > 0) {
132	        pb->total_written += (size_t)n;
133	    } else {
134	        syslog(LOG_ERR, "[%s] write_data(%zu) failed: %zd\n",
135	            TAG, len, n);
136	    }
137	
138	    return (int)n;
139	}
140	
141	void audio_playback_stop(audio_playback_t* pb)
142	{
143	    if (pb) {
144	        pb->stopped = 1;
145	        /* Force-stop the media player so write_data() unblocks
146	         * immediately if it is currently blocking in the audio
147	         * driver.  media_player_stop is safe to call from any
148	         * thread on NuttX. */
149	        if (pb->player) {
150	            media_player_stop(pb->player);
151	        }
152	    }
153	}
154	
155	void audio_playback_close(audio_playback_t* pb)
156	{
157	    if (!pb) {
158	        return;
159	    }
160	
161	    if (pb->player) {
162	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
163	            TAG, pb->total_written);
164	
165	        /* Always stop before close to unblock the AP-side media
166	         * player thread.  Without this, media_player_close with
167	         * pending_stop=1 waits for the AP reader to drain, but
168	         * the reader is blocked on rpmsg waiting for data that
169	         * will never come → watchdog fires after ~2 minutes. */
170	        media_player_stop(pb->player);
171	        usleep(50 * 1000); /* let AP-side process the stop */
172	        media_player_close(pb->player, 0);
173	
174	        s_active_player = NULL;
175	        syslog(LOG_INFO, "[%s] playback done\n", TAG);
176	    }
177	
178	    free(pb);
179	}

