提取 ai_ws_connect()：
```c
/* Open TCP socket + WS upgrade handshake to the local ai_agent.
 * Returns connected fd on success, -1 on failure. 30s RCVTIMEO set. */
static int ai_ws_connect(void)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0)
        return -1;
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(AI_WS_PORT);
    sa.sin_addr.s_addr = inet_addr(AI_WS_HOST);
    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0)
        {
            close(fd);
            return -1;
        }
    struct timeval tv;
    tv.tv_sec  = 30;
    tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    /* HTTP Upgrade handshake */
    {
        unsigned char rnd[16];
        char key_b64[64];
        char req[512];
        char hb[1024];
        for (int i = 0; i < 16; i++)
            rnd[i] = (unsigned char)(rand() & 0xFF);
        b64_encode(rnd, 16, key_b64, sizeof(key_b64));
        snprintf(req, sizeof(req),
                 "GET / HTTP/1.1\r\n"
                 "Host: %s:%d\r\n"
                 "Upgrade: websocket\r\n"
                 "Connection: Upgrade\r\n"
                 "Sec-WebSocket-Key: %s\r\n"
                 "Sec-WebSocket-Version: 13\r\n"
                 "\r\n",
                 AI_WS_HOST, AI_WS_PORT, key_b64);
        if (send(fd, req, strlen(req), 0) != (int)strlen(req))
            {
                close(fd);
                return -1;
            }
        int total = 0;
        while (total < (int)sizeof(hb) - 1)
            {
                int n = recv(fd, hb + total, sizeof(hb) - 1 - total, 0);
                if (n <= 0)
                    {
                        close(fd);
                        return -1;
                    }
                total += n;
                hb[total] = '\0';
                if (strstr(hb, "\r\n\r\n"))
                    break;
            }
        if (!strstr(hb, "101"))
            {
                close(fd);
                return -1;
            }
    }
    return fd;
}
```

