/* P53 方案A：语音控制（按住说话）——发送 {"type":"voice","action":"start|stop"}
 * 短连接 fire-and-forget，不等回复；ws_server 侧解析后调 voice_channel_start/stop。 */
static char g_ai_voice_action[8];
static volatile int g_ai_voice_busy;

static void *ai_voice_worker(void *arg)
{
    (void)arg;
    int fd = ai_ws_connect();
    if (fd >= 0)
        {
            char json[64];
            snprintf(json, sizeof(json),
                     "{\"type\":\"voice\",\"action\":\"%s\"}",
                     g_ai_voice_action);
            ws_send_text(fd, json);
            close(fd);
        }
    g_ai_voice_busy = 0;
    return NULL;
}

int dm_ai_voice(const char *action)
{
    if (!action || (strcmp(action, "start") != 0 && strcmp(action, "stop") != 0))
        return -1;
    if (g_ai_voice_busy)
        return -1;
    strncpy(g_ai_voice_action, action, sizeof(g_ai_voice_action) - 1);
    g_ai_voice_action[sizeof(g_ai_voice_action) - 1] = '\0';
    g_ai_voice_busy = 1;
    if (pthread_create(&g_ai_thread, NULL, ai_voice_worker, NULL) != 0)
        {
            g_ai_voice_busy = 0;
            return -1;
        }
    pthread_detach(g_ai_thread);
    return 0;
}
```

