 * 就绪后即全链路可用（当前状态联动为 UI 反馈，底层已真实触发）。 */
static void ai_voice_press_cb(lv_event_t *e)
{
    (void)e;
    reset_idle_timer();   /* 2026-08-11：交互防 idle 到期跳锁屏（铁律 4） */
    if (ai_status_lbl)
        lv_label_set_text(ai_status_lbl, "Listening...");
